 fondue","qty":300,"unit":"g","have":false},{"name":"bouillon de bœuf","plural":"bouillons de bœuf","qty":2,"unit":"","have":false},{"name":"oignon","plural":"oignons","qty":1,"unit":"","have":false},{"name":"gingembre frais","plural":"gingembre frais","qty":1,"unit":"","have":false},{"name":"badiane","plural":"badianes","qty":2,"unit":"","have":false},{"name":"sauce nuoc-mâm","plural":"sauce nuoc-mâm","qty":3,"unit":"c. à s.","have":false},{"name":"pousses de soja","plural":"pousses de soja","qty":150,"unit":"g","have":false},{"name":"coriandre","plural":"coriandre","qty":null,"unit":"","have":false},{"name":"citron vert","plural":"citrons verts","qty":1,"unit":"","have":false}],"steps":[{"text":"Fais griller l'oignon et le gingembre coupés en deux à la poêle, à sec.","timer":{"label":"Poêle","min":5}},{"text":"Mets-les dans 1,5 litre d'eau avec les bouillons, la badiane et le nuoc-mâm, et laisse frémir 40 min.","timer":{"label":"Cuisson","min":40}},{"text":"Fais cuire les nouilles selon le paquet.","timer":null},{"text":"Coupe le bœuf cru en tranches très fines.","timer":null},{"text":"Mets nouilles et bœuf dans les bols et verse le bouillon bouillant dessus : il cuit la viande.","timer":null},{"text":"Sers avec les pousses de soja, la coriandre et le citron vert.","timer":null}]},{"title":"Risotto aux champignons","intro":"Un riz crémeux cuit doucement dans le bouillon, avec des champignons et du parmesan.","minutes":35,"calories":560,"difficulty":"Moyen","imageSearch":"mushroom risotto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Plat italien","serves":4,"items":[{"name":"riz arborio","plural":"riz arborio","qty":320,"unit":"g","have":false},{"name":"champignon de Paris","plural":"champignons de Paris","qty":300,"unit":"g","have":false},{"name":"échalote","plural":"échalotes","qty":2,"unit":"","have":false},{"name":"vin blanc","plural":"vins blanc","qty":10,"unit":"cl","have":false},{"name":"bouillon de légumes","plural":"bouillons de légumes","q